input.new_string:
  # Issue #121: 0.9 also trips checkKinshipOverrides()'s documented "> 0.5"
  # warning (D6) before the strict PSD-bound error fires. Assert it explicitly
  # (edition 2 captures every emission, so the count is deliberately unpinned).
  expect_warning(
    expect_error(
      suppressMessages(gvaConvergence(fx$ped,
        pop = fx$pop, nMax = 800L, seed = 11L, kinshipOverrides = badVal
      )),
      "above the maximum"
    ),
    "off-diagonal value\\(s\\) > 0.5"
  )
})

